const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=ts=>{if(!ts)return'';const d=typeof ts.toDate==='function'?ts.toDate():new Date(ts);return Number.isNaN(d.getTime())?'':d.toLocaleString()};
function loadJSON(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}}
function saveJSON(key,val){try{localStorage.setItem(key,JSON.stringify(val));return true}catch{return false}}
function defaultProgress(){return{questionHistory:{},flags:{},assessments:[],updatedAt:null}}
function getProgress(){const p=loadJSON(KEYS.progress,defaultProgress());p.questionHistory=p.questionHistory||{};p.flags=p.flags||{};p.assessments=p.assessments||[];return p}
function setProgress(p){p.updatedAt=Date.now();saveJSON(KEYS.progress,p)}
function getStudyStore(){return loadJSON(KEYS.study,{})}
function studyKey(session){return session.studyKey||''}
function studySnapshotExists(key){return Boolean(getStudyStore()[key])}
function saveStudySnapshot(session){if(session?.mode!=='study'||!studyKey(session))return;const store=getStudyStore();store[studyKey(session)]=sessionToDraft(session,true);saveJSON(KEYS.study,store)}
function deleteStudySnapshot(key){const store=getStudyStore();delete store[key];saveJSON(KEYS.study,store)}
function readStudySnapshot(key){return getStudyStore()[key]||null}
function saveAutosave(reason='interaction'){if(!activeSession||activeSession.submitted)return;const draft=sessionToDraft(activeSession,false);draft.reason=reason;draft.savedAt=Date.now();saveJSON(KEYS.autosave,draft);if(activeSession.mode==='study')saveStudySnapshot(activeSession);updateAutosaveIndicator()}
function clearAutosave(){try{localStorage.removeItem(KEYS.autosave)}catch{}}
function readAutosave(){return loadJSON(KEYS.autosave,null)}
function sessionToDraft(s,studyOnly){return{version:1,id:s.id,kind:s.kind,mode:s.mode,title:s.title,subtitle:s.subtitle,questionIds:s.questionIds,answers:s.answers,revealedIds:[...s.revealedIds],expandedIds:[...s.expandedIds],recordedIds:[...s.recordedIds],viewMode:s.viewMode,currentIndex:s.currentIndex,deadline:s.deadline||null,durationMinutes:s.durationMinutes||null,studyKey:s.studyKey||'',meta:s.meta||{},submitted:Boolean(s.submitted),savedAt:Date.now(),studyOnly:Boolean(studyOnly)}}
function draftToSession(d){if(!d||!Array.isArray(d.questionIds))return null;return{id:d.id||(globalThis.crypto?.randomUUID?.()||('pr-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12))),kind:d.kind,mode:d.mode,title:d.title,subtitle:d.subtitle,questionIds:d.questionIds,answers:d.answers||{},revealedIds:new Set(d.revealedIds||[]),expandedIds:new Set(d.expandedIds||[]),recordedIds:new Set(d.recordedIds||[]),viewMode:d.viewMode==='one'?'one':'continuous',currentIndex:Number(d.currentIndex)||0,deadline:d.deadline||null,durationMinutes:d.durationMinutes||null,studyKey:d.studyKey||'',meta:d.meta||{},submitted:Boolean(d.submitted)}}
function questionById(id){return QUESTION_DETAILS.get(Number(id))||metaQuestionById(id)}
function footer(){return `<footer class="site-footer"><div class="footer-inner"><p class="footer-verse">${esc(VERSES[verseIndex])}</p><p class="source-acknowledgement">Source acknowledgement: Question and explanation text is reproduced from the user-supplied source PDFs for personal educational revision. Source/page metadata is shown with each question. PDF text extraction and structuring were automated; verify against the cited source pages before clinical or examination use.</p></div></footer>`}
function header(active=''){return `<header class="site-header"><div class="header-inner"><button class="brand" data-route="home"><span class="brand-mark">PR</span><span><strong>Primary Revision</strong><small>Physiology • Pharmacology</small></span></button><nav class="main-nav"><button class="${active==='topics'?'active':''}" data-route="topics">Study by Topic</button><button class="${active==='mock'?'active':''}" data-route="mock">Mock exam</button><button class="${active==='sources'?'active':''}" data-route="sources">Original sources</button><button class="${active==='discussions'?'active':''}" data-route="discussions">Discussions</button><button class="${active==='search'?'active':''}" data-route="search">Search</button></nav><button class="header-search-button" data-route="search" aria-label="Search question bank">⌕<span>Search</span></button></div></header>`}
function mobileMenu(active=''){const inSession=routeState.name==='session';return `<nav class="mobile-bottom-menu" ${inSession?'hidden':''} aria-label="Primary Revision modes"><button class="${active==='topics'?'active':''}" data-route="topics">▦ Study</button><button class="${active==='mock'?'active':''}" data-route="mock">◷ Mock</button><button class="${active==='sources'?'active':''}" data-route="sources">▤ Sources</button><button class="${active==='discussions'?'active':''}" data-route="discussions">◌ Discuss</button></nav>`}
function shell(content,active=''){return `<div class="site-shell">${header(active)}<main>${content}</main>${footer()}${mobileMenu(active)}</div>`}
function navigate(name,params={}){if(routeState.name!==name||JSON.stringify(routeState.params||{})!==JSON.stringify(params)){verseIndex=(verseIndex+1)%VERSES.length}routeState={name,params};window.scrollTo({top:0,behavior:'auto'});render()}
function sourceQLabel(q){return q.sourceQuestionLabel||`Question #${q.sourceQuestion}`}
function sourceLabel(q){return `${q.source} • ${sourceQLabel(q)} • PDF p.${q.questionPage}`}
function getDomains(){return [...new Set(QUESTIONS.map(q=>q.domain).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function getLevels(){return [...new Set(QUESTIONS.map(q=>q.level).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function getSourceGroups(){const groups=Object.values(QUESTIONS.reduce((a,q)=>{a[q.sourceCode]??={code:q.sourceCode,name:q.source,levels:new Set(),domains:new Set(),questions:[]};a[q.sourceCode].levels.add(q.level);a[q.sourceCode].domains.add(q.domain);a[q.sourceCode].questions.push(q);return a},{}));groups.forEach(g=>{g.questions.sort((a,b)=>(a.sourceOrder??a.sourceQuestion??a.id)-(b.sourceOrder??b.sourceQuestion??b.id));g.level=[...g.levels].filter(Boolean).join(' / ');g.domain=g.domains.size===1?[...g.domains][0]:'Mixed domains'});return groups}
function getTopics(){const m={};QUESTIONS.forEach(q=>{m[q.topic]??={name:q.topic,domains:new Set(),questions:[]};m[q.topic].domains.add(q.domain);m[q.topic].questions.push(q)});return Object.values(m).map(t=>({...t,domain:t.domains.size===1?[...t.domains][0]:'Mixed'})).sort((a,b)=>a.domain.localeCompare(b.domain)||a.name.localeCompare(b.name))}
function groupSourceSets(items){const labelled=items.every(q=>q.sourceQuestionLabel&&/^(.*) Q\d+$/i.test(q.sourceQuestionLabel));if(!labelled)return chunks(items).map((questions,i)=>({label:`Set ${i+1}`,questions}));const groups=[];const map=new Map();items.forEach(q=>{const m=q.sourceQuestionLabel.match(/^(.*) Q\d+$/i);const label=m?m[1]:'Questions';if(!map.has(label)){const g={label,questions:[]};map.set(label,g);groups.push(g)}map.get(label).questions.push(q)});return groups}
function tableHTML(q,component){const tables=component==='question'?q.questionTables:q.answerTables;if(!(tables||[]).length)return'';return `<div class="table-swipe-hint" aria-hidden="true">↔ Swipe to view full table</div>`+(tables||[]).map(t=>t.html||'').join('')}
function chunks(arr,n=SET_SIZE){const out=[];for(let i=0;i<arr.length;i+=n)out.push(arr.slice(i,i+n));return out}
function getHistory(id,p=getProgress()){return p.questionHistory[id]||{studyChecks:0,studyCorrect:0,assessmentAttempts:0,assessmentCorrect:0,lastStudyCorrect:null,lastAssessmentCorrect:null,lastAssessmentAnswered:null,needsReview:false}}
function historyNeedsReview(h){if(typeof h.needsReview==='boolean')return h.needsReview;const legacyStudyWrong=(h.studyChecks||0)>(h.studyCorrect||0);return h.lastAssessmentCorrect===false||h.lastAssessmentAnswered===false||legacyStudyWrong}
function reviewQueueStats(p=getProgress()){const ids=new Set(),incorrectIds=new Set(),unansweredIds=new Set(),flaggedIds=new Set();Object.entries(p.questionHistory||{}).forEach(([id,h])=>{const qid=Number(id);if(historyNeedsReview(h)){ids.add(qid);if(h.lastAssessmentAnswered===false)unansweredIds.add(qid);else incorrectIds.add(qid)}});Object.entries(p.flags||{}).forEach(([id,v])=>{if(v){const qid=Number(id);ids.add(qid);flaggedIds.add(qid)}});return{ids:[...ids],count:ids.size,incorrect:incorrectIds.size,unanswered:unansweredIds.size,flagged:flaggedIds.size}}
function attemptedIds(p=getProgress()){return new Set(Object.entries(p.questionHistory).filter(([,h])=>(h.studyChecks||0)+(h.assessmentAttempts||0)>0).map(([id])=>Number(id)))}
function studiedIds(p=getProgress()){return new Set(Object.entries(p.questionHistory).filter(([,h])=>(h.studyChecks||0)>0).map(([id])=>Number(id)))}
function assessmentIds(p=getProgress()){return new Set(Object.entries(p.questionHistory).filter(([,h])=>(h.assessmentAttempts||0)>0).map(([id])=>Number(id)))}
function modeCoverage(p){const studies=studiedIds(p);const assessed=assessmentIds(p);const mockIds=new Set();const sourceIds=new Set();p.assessments.forEach(a=>{(a.questionIds||[]).forEach(id=>{if(a.kind==='mock')mockIds.add(id);if(a.kind==='source')sourceIds.add(id)})});return{study:studies.size,assessment:assessed.size,mock:mockIds.size,source:sourceIds.size}}
function trendInfo(scores){if(scores.length<2)return{label:'Not enough data',delta:0};const recent=scores.slice(-5);const delta=recent[recent.length-1]-recent[0];return{label:delta>=5?'↑ Improving':delta<=-5?'↓ Declining':'→ Stable',delta}}
function sparkline(scores){const vals=scores.slice(-5);if(vals.length<2)return'';const w=160,h=38,pad=4,min=Math.min(...vals,0),max=Math.max(...vals,100),range=Math.max(1,max-min);const pts=vals.map((v,i)=>`${pad+i*(w-2*pad)/(vals.length-1)},${h-pad-(v-min)*(h-2*pad)/range}`).join(' ');return `<div class="sparkline"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Recent assessment scores"><polyline points="${pts}" fill="none" stroke="#176f63" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></div>`}
function performanceDashboard(){const p=getProgress(),attempted=attemptedIds(p),cov=Math.round(attempted.size/QUESTIONS.length*100),mc=modeCoverage(p);const assessments=p.assessments.filter(a=>a.completed&&Number.isFinite(a.pct));const scores=assessments.map(a=>a.pct),last5=scores.slice(-5);const recent=last5.length?Math.round(last5.reduce((a,b)=>a+b,0)/last5.length):null;const latest=scores.length?Math.round(scores.at(-1)):null;const best=scores.length?Math.round(Math.max(...scores)):null;const trend=trendInfo(scores);const studyChecks=Object.values(p.questionHistory).reduce((n,h)=>n+(h.studyChecks||0),0);const assessedEvents=Object.values(p.questionHistory).reduce((n,h)=>n+(h.assessmentAttempts||0),0);
 const readiness=getTopics().map(t=>{let attempts=0,correct=0,seen=0;t.questions.forEach(q=>{const h=getHistory(q.id,p);attempts+=h.assessmentAttempts||0;correct+=h.assessmentCorrect||0;if((h.studyChecks||0)+(h.assessmentAttempts||0)>0)seen++});const acc=attempts?Math.round(correct/attempts*100):null,coverage=Math.round(seen/t.questions.length*100);let label='Insufficient data',cls='insufficient',priority=999;if(attempts>=5){if(acc>=70){label='Strong';cls='strong';priority=300-acc}else if(acc>=50){label='Developing';cls='developing';priority=100+acc}else{label='Needs attention';cls='attention';priority=acc}}return{...t,attempts,acc,coverage,seen,label,cls,priority}}).sort((a,b)=>a.priority-b.priority||a.coverage-b.coverage).slice(0,8);
 const reviewStats=reviewQueueStats(p),incorrect=reviewStats.incorrect,unanswered=reviewStats.unanswered,flagged=reviewStats.flagged,reviewCount=reviewStats.count;
 return `<section class="progress-section"><div class="page-width"><div class="card"><div class="progress-card-heading"><div><p class="eyebrow">Your Primary progress</p><h2>${recent===null?'Start an assessment':recent+'% recent average'}${assessments.length?` · ${assessments.length} assessment${assessments.length===1?'':'s'}`:''}</h2></div><span class="status-dot"></span></div><div class="coverage-block"><div class="coverage-label"><strong>${attempted.size} / ${QUESTIONS.length} questions</strong><span>${cov}% overall coverage</span></div><div class="coverage-track"><span style="width:${cov}%"></span></div><div class="mode-coverage"><span>Study <strong>${mc.study}</strong></span><span>Test/Timed <strong>${mc.assessment}</strong></span><span>Mock <strong>${mc.mock}</strong></span><span>Original sources <strong>${mc.source}</strong></span></div></div><div class="performance-grid"><div><span>Latest assessment</span><strong>${latest===null?'—':latest+'%'}</strong><small>${assessments.length?esc(assessments.at(-1).title):'No completed assessment'}</small></div><div><span>Recent average</span><strong>${recent===null?'—':recent+'%'}</strong><small>Last ${last5.length||0} assessments</small></div><div><span>Best assessment</span><strong>${best===null?'—':best+'%'}</strong><small>Completed assessments only</small></div><div><span>Recent trend</span><strong style="font-size:17px">${trend.label}</strong><small>Study mode excluded</small>${sparkline(scores)}</div></div><p class="eyebrow">Learning activity</p><div class="learning-row"><div><strong>${studiedIds(p).size}</strong><span>Questions studied</span></div><div><strong>${studyChecks}</strong><span>Study answer checks</span></div><div><strong>${assessedEvents}</strong><span>Assessment answers recorded</span></div></div><div class="readiness-heading"><p class="eyebrow">Priority topics</p><button class="text-link" data-route="topics">View all ${getTopics().length} topics →</button></div><div class="readiness-list">${readiness.map(r=>`<div class="readiness-item"><div class="readiness-top"><span class="readiness-name">${esc(r.name)}</span><div class="readiness-inline"><small>${r.attempts>=5?`${r.acc}% accuracy`:'No readiness score'}</small><small>${r.seen}/${r.questions.length} seen</small><b class="readiness-badge ${r.cls}">${r.label}</b></div></div><div class="readiness-coverage"><div class="mini-track"><i style="width:${r.coverage}%"></i></div><small>${r.coverage}%</small></div></div>`).join('')}</div><button class="review-queue-row" data-action="review-queue" ${reviewCount?'':'disabled'}><span><strong>Review next — ${reviewCount} question${reviewCount===1?'':'s'}</strong><small>${incorrect} incorrect · ${unanswered} unanswered · ${flagged} flagged</small></span><b>Review →</b></button><div class="progress-reset"><button class="secondary-button" data-action="export-progress">Export progress</button><button class="secondary-button" data-action="import-progress">Import progress</button><input id="progress-import-file" type="file" accept="application/json,.json" hidden><button class="danger-button" data-action="reset-all">Reset all progress</button></div></div></div></section>`}
function savedSessionRecords(){const records=[],auto=readAutosave(),seen=new Set();if(auto&&!auto.submitted){records.push({type:'autosave',key:'',draft:auto});if(auto.id)seen.add(auto.id)}Object.entries(getStudyStore()).forEach(([key,draft])=>{if(!draft||draft.submitted)return;if(draft.id&&seen.has(draft.id))return;records.push({type:'study',key,draft})});return records.sort((a,b)=>(b.draft.savedAt||0)-(a.draft.savedAt||0))}
function firebaseDiscussionEnabled(){const c=window.PRIMARY_FIREBASE_CONFIG||{};return Boolean(c.enabled&&c.apiKey&&c.projectId&&c.appId)}
function firebaseDiscussionReady(){return firebaseDiscussionEnabled()&&discussionFirebaseState==='ready'&&discussionDb&&discussionAuth&&currentDiscussionUid}
function discussionThreadKey(qid){return `primary-q-${Number(qid)}`}
function hashString(s){let h=2166136261;for(let i=0;i<String(s).length;i++){h^=String(s).charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function anonymousDisplayName(uid){const adjectives=['Brilliant','Calm','Careful','Curious','Focused','Kind','Precise','Steady','Thoughtful','Wise'];const drugs=['Dexmedetomidine','Ketamine','Lidocaine','Propofol','Remifentanil','Rocuronium','Sevoflurane','Sugammadex','Thiopentone','Vasopressin'];const h=hashString(uid||'primary-revision');return `${adjectives[h%adjectives.length]} ${drugs[Math.floor(h/adjectives.length)%drugs.length]} ${100+(h%900)}`}
