function firebaseMillis(v){if(!v)return 0;if(typeof v.toMillis==='function')return v.toMillis();if(typeof v.toDate==='function')return v.toDate().getTime();if(typeof v.seconds==='number')return v.seconds*1000+Math.floor((v.nanoseconds||0)/1e6);const n=Number(v);return Number.isFinite(n)?n:0}
function loadExternalScript(src,id){return new Promise((resolve,reject)=>{if(window.firebase&&id==='firebase-app-sdk'){resolve();return}const existing=document.getElementById(id);if(existing){if(existing.dataset.loaded==='1'){resolve();return}existing.addEventListener('load',()=>resolve(),{once:true});existing.addEventListener('error',()=>reject(new Error('Unable to load '+src)),{once:true});return}const el=document.createElement('script');el.id=id;el.src=src;el.async=true;el.crossOrigin='anonymous';el.onload=()=>{el.dataset.loaded='1';resolve()};el.onerror=()=>reject(new Error('Unable to load '+src));document.head.appendChild(el)})}
function friendlyFirebaseError(err){const code=String(err?.code||'');if(code.includes('operation-not-allowed'))return'Anonymous Authentication is not enabled for this Firebase project.';if(code.includes('unauthorized-domain'))return'This website hostname is not listed in Firebase Authentication → Authorized domains.';if(code.includes('permission-denied'))return'Firestore denied the request. Publish the Primary-DISC02 firestore.rules file.';if(code.includes('unavailable')||!navigator.onLine)return'Discussions require an internet connection.';return err?.message||'Firebase discussions are temporarily unavailable.'}
function discussionConnectionHTML(){if(!firebaseDiscussionEnabled())return `<div class="discussion-connection error"><strong>Discussion unavailable.</strong> Firebase has not been configured.</div>`;if(discussionFirebaseState==='ready'){const name=anonymousDisplayName(currentDiscussionUid);return `<div class="discussion-connection ready"><span class="discussion-author-chip"><i>${esc(initialsForName(name))}</i><span>Connected as <strong>${esc(name)}</strong></span></span></div>`}if(discussionFirebaseState==='offline')return `<div class="discussion-connection offline"><strong>Offline.</strong> The SBA bank remains available, but shared discussions require an internet connection.</div>`;if(discussionFirebaseState==='error')return `<div class="discussion-connection error"><strong>Discussion connection failed.</strong> ${esc(discussionFirebaseError)}</div>`;return `<div class="discussion-connection"><strong>Connecting…</strong> Signing in anonymously to the PrimarySBA discussion service.</div>`}
function threadFromSnapshot(doc){const d=doc.data()||{};return{id:doc.id,...d,questionId:Number(d.questionId),commentCount:Number(d.commentCount)||0,createdAt:firebaseMillis(d.createdAt),updatedAt:firebaseMillis(d.updatedAt),isMine:discussionMyThreadKeys.has(doc.id)}}
function commentFromSnapshot(doc){const d=doc.data()||{};return{id:doc.id,...d,createdAt:firebaseMillis(d.createdAt),deletedAt:firebaseMillis(d.deletedAt)}}
function normalizeDiscussionComments(items){const byId=new Map(items.map(c=>[c.id,{...c,replies:[]}]));const roots=[];for(const c of byId.values()){if(!c.parentId)roots.push(c)}for(const c of byId.values()){if(!c.parentId)continue;const root=byId.get(c.rootId);if(root&&root!==c)root.replies.push(c);else roots.push(c)}const sort=(a,b)=>(a.createdAt||0)-(b.createdAt||0)||String(a.id).localeCompare(String(b.id));roots.sort(sort);roots.forEach(r=>r.replies.sort(sort));return roots}
function findCachedDiscussionComment(qid,commentId){const roots=discussionCommentsCache[discussionThreadKey(qid)]||[];for(const r of roots){if(r.id===commentId)return r;const x=(r.replies||[]).find(c=>c.id===commentId);if(x)return x}return null}
function discussionCommentHTML(c,qid,isReply=false){const author=anonymousDisplayName(c.uid||'primary-revision'),mine=Boolean(currentDiscussionUid&&c.uid===currentDiscussionUid),deleted=Boolean(c.deleted),replyOpen=discussionReplyTarget&&discussionReplyTarget.qid===qid&&discussionReplyTarget.commentId===c.id;return `<div class="discussion-comment ${isReply?'discussion-reply':''}" data-comment-id="${esc(c.id||'')}"><div class="discussion-avatar">${esc(initialsForName(author))}</div><div class="discussion-comment-body"><div class="discussion-comment-head"><strong>${esc(author)}</strong><small>${c.createdAt?esc(fmtDate(c.createdAt)):''}</small></div><p>${deleted?'<em>Comment deleted by author.</em>':esc(c.text||'')}</p><div class="discussion-comment-actions">${deleted?'':`<button data-action="reply-discussion" data-qid="${qid}" data-comment-id="${esc(c.id||'')}">Reply</button><button data-action="report-discussion" data-qid="${qid}" data-comment-id="${esc(c.id||'')}">Report</button>${mine?`<button data-action="delete-discussion" data-qid="${qid}" data-comment-id="${esc(c.id||'')}">Delete</button>`:''}`}</div>${replyOpen&&!deleted?`<div class="discussion-reply-compose"><textarea data-reply-text="${esc(c.id)}" maxlength="2000" placeholder="Write a reply…"></textarea><div class="discussion-reply-compose-actions"><button class="secondary-button" data-action="cancel-reply-discussion" data-qid="${qid}">Cancel</button><button class="primary-button" data-action="send-reply-discussion" data-qid="${qid}" data-comment-id="${esc(c.id)}">Post reply</button></div></div>`:''}${(c.replies||[]).map(r=>discussionCommentHTML(r,qid,true)).join('')}</div></div>`}
function discussionCommentsHTML(q){const comments=discussionCommentsCache[discussionThreadKey(q.id)]||[];return comments.length?comments.map(c=>discussionCommentHTML(c,q.id,false)).join(''):`<p class="discussion-empty-note">No comments yet. Start the discussion for this question.</p>`}
function discussionPanelHTML(q){const count=discussionThreadsCache.find(t=>Number(t.questionId)===q.id)?.commentCount||0,ready=firebaseDiscussionReady(),name=ready?anonymousDisplayName(currentDiscussionUid):'';return `<section class="discussion-panel" data-discussion-qid="${q.id}" data-thread-key="${discussionThreadKey(q.id)}"><div class="discussion-panel-head"><h4>Discussion</h4><span class="discussion-count">${count}</span></div><p class="discussion-warning">User-contributed discussion may contain errors. Verify against authoritative sources.</p><div data-discussion-status>${discussionConnectionHTML()}</div><div class="discussion-comments" data-discussion-comments-host>${discussionCommentsHTML(q)}</div><div class="discussion-compose"><textarea aria-label="Add a discussion comment" maxlength="2000" placeholder="Add a comment…" ${ready?'':'disabled'}></textarea><div class="discussion-compose-row"><small>${ready?`Posting as ${esc(name)}. Your anonymous Firebase identity is stable on this browser unless site data is cleared.`:'Posting becomes available when Firebase is connected.'}</small><button class="primary-button" data-action="post-discussion" data-qid="${q.id}" ${ready?'':'disabled'}>Post anonymously</button></div></div></section>`}
function discussionQuestionContext(q){const correctText=q.correctAnswerText||((q.options.find(o=>o.key===q.correctAnswer)||{}).text||'');return `<article class="discussion-question-card"><span class="discussion-source-chip">${esc(sourceLabel(q))}</span><div class="question-stem">${q.stemHtml||esc(q.stem)}</div>${visualHTML(q,'question')}${tableHTML(q,'question')}<div class="options">${q.options.map(o=>`<div class="option"><span class="option-key">${esc(o.key)}</span><span class="option-text">${o.html||esc(o.text)}</span></div>`).join('')}</div><details class="discussion-context" open><summary>Source answer and explanation</summary><div class="correct-answer-line"><span>Correct answer</span><strong>${esc(q.correctAnswer)}${correctText?'. '+esc(correctText):''}</strong></div><div class="explanation-section"><h4>Explanation</h4>${visualHTML(q,'answer')}<div class="explanation-prose">${q.explanationHtml||`<p>${esc(q.explanation)}</p>`}</div>${tableHTML(q,'answer')}</div>${q.bottomLine?`<div class="explanation-section bottom-line"><h4>Bottom Line</h4><div class="explanation-prose">${q.bottomLineHtml||`<p>${esc(q.bottomLine)}</p>`}</div></div>`:''}</details>${discussionPanelHTML(q)}</article>`}
function discussionThreadCards(){if(!discussionThreadsCache.length)return'';let rows=discussionThreadsCache.map(t=>({...t,isMine:discussionMyThreadKeys.has(t.id)}));if(discussionScope==='mine')rows=rows.filter(t=>t.isMine);if(discussionView==='topic')rows.sort((a,b)=>String(a.topic||'').localeCompare(String(b.topic||''))||((b.updatedAt||0)-(a.updatedAt||0)));else if(discussionView==='source')rows.sort((a,b)=>String(a.source||'').localeCompare(String(b.source||''))||((b.updatedAt||0)-(a.updatedAt||0)));else rows.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));return rows.map(t=>{const q=questionById(t.questionId);if(!q)return'';return `<button class="discussion-thread-card" data-discussion-question="${q.id}"><p>${esc(discussionView==='topic'?q.topic:discussionView==='source'?q.source:'Q'+q.id+' · '+q.topic)}</p><h3>${esc(q.stem)}</h3><div class="discussion-thread-meta"><span>${Number(t.commentCount)||0} comment${Number(t.commentCount)===1?'':'s'}${t.isMine?' · participated':''}</span><span>${t.updatedAt?esc(fmtDate(t.updatedAt)):'No activity yet'}</span></div></button>`}).join('')}
function discussionsPage(){const cards=discussionThreadCards(),ready=firebaseDiscussionReady();let emptyTitle='No discussions yet',emptyText='Question discussions will appear here when candidates start commenting.';if(discussionFirebaseState==='loading'){emptyTitle='Connecting discussions…';emptyText='Signing in anonymously and loading shared Primary Revision threads.'}else if(discussionFirebaseState==='offline'){emptyTitle='Discussions are offline';emptyText='The question bank remains usable offline. Reconnect to browse or post shared discussions.'}else if(discussionFirebaseState==='error'){emptyTitle='Discussion connection failed';emptyText=discussionFirebaseError}else if(discussionScope==='mine'&&ready){emptyTitle='No discussions from this browser yet';emptyText='Threads you comment on with this anonymous identity will appear here.'}return shell(`<section class="page-heading"><div class="page-width"><p class="eyebrow">Discussions</p><h1>Shared question discussions</h1><p>Each Primary Revision question has one stable thread, shared across Study by Topic, Original Sources, Mock Exam, Review Questions and restored sessions.</p><div style="margin-top:14px">${discussionConnectionHTML()}</div><div class="discussion-tabs"><button class="${discussionScope==='all'?'active':''}" data-discussion-scope="all">All discussions</button><button class="${discussionScope==='mine'?'active':''}" data-discussion-scope="mine">My discussions</button></div><div class="discussion-tabs"><button class="${discussionView==='recent'?'active':''}" data-discussion-view="recent">Recent</button><button class="${discussionView==='topic'?'active':''}" data-discussion-view="topic">By topic</button><button class="${discussionView==='source'?'active':''}" data-discussion-view="source">By source</button></div>${cards?`<div class="discussion-list">${cards}</div>`:`<div class="discussion-empty"><strong>${esc(emptyTitle)}</strong><p>${esc(emptyText)}</p></div>`}</div></section>`,'discussions')}
function discussionDetailPage(id){const q=questionById(id);if(!q)return discussionsPage();return shell(`<section class="page-heading"><div class="page-width"><button class="secondary-button" data-route="discussions">← Discussions</button><p class="eyebrow" style="margin-top:18px">Discussion · Q${q.id}</p><h1>${esc(q.topic)}</h1><p>Shared thread key: ${discussionThreadKey(q.id)}</p><div style="margin-top:22px">${discussionQuestionContext(q)}</div></div></section>`,'discussions')}
function updateDiscussionPanelDOM(qid){const q=questionById(qid);if(!q)return;document.querySelectorAll(`.discussion-panel[data-discussion-qid="${qid}"]`).forEach(panel=>{const count=discussionThreadsCache.find(t=>Number(t.questionId)===qid)?.commentCount||0;const badge=panel.querySelector('.discussion-count');if(badge)badge.textContent=String(count);const status=panel.querySelector('[data-discussion-status]');if(status)status.innerHTML=discussionConnectionHTML();const host=panel.querySelector('[data-discussion-comments-host]');if(host)host.innerHTML=discussionCommentsHTML(q);const ta=panel.querySelector('.discussion-compose>textarea');const btn=panel.querySelector('[data-action="post-discussion"]');const small=panel.querySelector('.discussion-compose-row small');const ready=firebaseDiscussionReady();if(ta)ta.disabled=!ready;if(btn)btn.disabled=!ready;if(small)small.textContent=ready?`Posting as ${anonymousDisplayName(currentDiscussionUid)}. Your anonymous Firebase identity is stable on this browser unless site data is cleared.`:'Posting becomes available when Firebase is connected.';bindDiscussionActions(panel)})}
function bindDiscussionActions(root=document){root.querySelectorAll('[data-action]').forEach(el=>{if(el.dataset.actionBound==='1')return;const a=el.dataset.action;if(['post-discussion','reply-discussion','send-reply-discussion','cancel-reply-discussion','report-discussion','delete-discussion'].includes(a)){el.dataset.actionBound='1';el.addEventListener('click',handleAction)}})}
function syncDiscussionCommentSubscriptions(){if(!firebaseDiscussionReady())return;const visible=new Set([...document.querySelectorAll('.discussion-panel[data-discussion-qid]')].map(p=>Number(p.dataset.discussionQid)).filter(Boolean));for(const [qid,unsub] of discussionCommentUnsubs){if(!visible.has(qid)){try{unsub()}catch{}discussionCommentUnsubs.delete(qid)}}for(const qid of visible)ensureDiscussionCommentsSubscription(qid)}
function ensureDiscussionCommentsSubscription(qid){if(!firebaseDiscussionReady()||discussionCommentUnsubs.has(qid))return;const key=discussionThreadKey(qid);const unsub=discussionDb.collection('discussions').doc(key).collection('comments').orderBy('createdAt','asc').onSnapshot(snap=>{const flat=snap.docs.map(commentFromSnapshot);discussionCommentsCache[key]=normalizeDiscussionComments(flat);updateDiscussionPanelDOM(qid)},err=>{discussionFirebaseError=friendlyFirebaseError(err);updateDiscussionPanelDOM(qid)});discussionCommentUnsubs.set(qid,unsub)}
function stopDiscussionListeners(){if(discussionThreadsUnsub){try{discussionThreadsUnsub()}catch{}discussionThreadsUnsub=null}if(discussionMineUnsub){try{discussionMineUnsub()}catch{}discussionMineUnsub=null}for(const [,u] of discussionCommentUnsubs){try{u()}catch{}}discussionCommentUnsubs.clear()}
function startDiscussionListeners(){if(!firebaseDiscussionReady())return;if(!discussionThreadsUnsub)discussionThreadsUnsub=discussionDb.collection('discussions').orderBy('updatedAt','desc').onSnapshot(snap=>{discussionThreadsCache=snap.docs.map(threadFromSnapshot);if(routeState.name==='discussions')render();else document.querySelectorAll('.discussion-panel[data-discussion-qid]').forEach(p=>updateDiscussionPanelDOM(Number(p.dataset.discussionQid)))},err=>{discussionFirebaseState='error';discussionFirebaseError=friendlyFirebaseError(err);if(routeState.name==='discussions')render();else document.querySelectorAll('.discussion-panel[data-discussion-qid]').forEach(p=>updateDiscussionPanelDOM(Number(p.dataset.discussionQid)))});if(!discussionMineUnsub)discussionMineUnsub=discussionDb.collection('userDiscussionThreads').doc(currentDiscussionUid).collection('threads').onSnapshot(snap=>{discussionMyThreadKeys=new Set(snap.docs.map(d=>d.id));discussionThreadsCache=discussionThreadsCache.map(t=>({...t,isMine:discussionMyThreadKeys.has(t.id)}));if(routeState.name==='discussions'&&discussionScope==='mine')render()},()=>{});syncDiscussionCommentSubscriptions()}
async function initFirebaseDiscussions(){if(!firebaseDiscussionEnabled()){discussionFirebaseState='error';discussionFirebaseError='Firebase has not been configured.';return}if(discussionInitPromise)return discussionInitPromise;discussionInitPromise=(async()=>{discussionFirebaseState=navigator.onLine?'loading':'offline';discussionFirebaseError='';if(!navigator.onLine){if(routeState.name==='discussions')render();else document.querySelectorAll('.discussion-panel').forEach(p=>updateDiscussionPanelDOM(Number(p.dataset.discussionQid)));throw new Error('offline')}try{const v='12.18.0';await loadExternalScript(`https://www.gstatic.com/firebasejs/${v}/firebase-app-compat.js`,'firebase-app-sdk');await loadExternalScript(`https://www.gstatic.com/firebasejs/${v}/firebase-auth-compat.js`,'firebase-auth-sdk');await loadExternalScript(`https://www.gstatic.com/firebasejs/${v}/firebase-firestore-compat.js`,'firebase-firestore-sdk');const cfg={...window.PRIMARY_FIREBASE_CONFIG};delete cfg.enabled;const app=window.firebase.apps?.length?window.firebase.app():window.firebase.initializeApp(cfg);discussionAuth=window.firebase.auth(app);discussionDb=window.firebase.firestore(app);await discussionAuth.setPersistence(window.firebase.auth.Auth.Persistence.LOCAL);let user=discussionAuth.currentUser;if(!user)user=(await discussionAuth.signInAnonymously()).user;currentDiscussionUid=user.uid;discussionFirebaseState='ready';discussionFirebaseError='';startDiscussionListeners();if(routeState.name==='discussions')render();else document.querySelectorAll('.discussion-panel').forEach(p=>updateDiscussionPanelDOM(Number(p.dataset.discussionQid)));return user}catch(err){discussionFirebaseState=navigator.onLine?'error':'offline';discussionFirebaseError=friendlyFirebaseError(err);if(routeState.name==='discussions')render();else document.querySelectorAll('.discussion-panel').forEach(p=>updateDiscussionPanelDOM(Number(p.dataset.discussionQid)));throw err}finally{if(discussionFirebaseState!=='ready')discussionInitPromise=null}})();return discussionInitPromise}
async function postDiscussionComment(qid,text,parentId=''){if(!firebaseDiscussionReady())throw new Error('Discussion service is not connected.');const q=questionById(qid);if(!q)throw new Error('Question not found.');text=String(text||'').trim();if(!text)throw new Error('Enter a comment first.');if(text.length>2000)throw new Error('Comments are limited to 2000 characters.');const key=discussionThreadKey(qid),threadRef=discussionDb.collection('discussions').doc(key),commentRef=threadRef.collection('comments').doc(),myRef=discussionDb.collection('userDiscussionThreads').doc(currentDiscussionUid).collection('threads').doc(key),FV=window.firebase.firestore.FieldValue;await discussionDb.runTransaction(async tx=>{const threadSnap=await tx.get(threadRef);const mySnap=await tx.get(myRef);let rootId=commentRef.id;if(parentId){const parentRef=threadRef.collection('comments').doc(parentId),parentSnap=await tx.get(parentRef);if(!parentSnap.exists||parentSnap.data().deleted)throw new Error('That comment is no longer available for replies.');rootId=parentSnap.data().rootId||parentId}const now=FV.serverTimestamp(),comment={threadKey:key,questionId:q.id,uid:currentDiscussionUid,text,parentId:parentId||'',rootId,createdAt:now,deleted:false};tx.set(commentRef,comment);if(threadSnap.exists){const count=Number(threadSnap.data().commentCount)||0;tx.update(threadRef,{updatedAt:now,commentCount:count+1,lastCommentId:commentRef.id,lastActorUid:currentDiscussionUid})}else tx.set(threadRef,{threadKey:key,questionId:q.id,topic:String(q.topic||''),source:String(q.source||''),sourceCode:String(q.sourceCode||''),domain:String(q.domain||''),createdAt:now,updatedAt:now,commentCount:1,lastCommentId:commentRef.id,lastActorUid:currentDiscussionUid});if(mySnap.exists){const mine=Number(mySnap.data().commentCount)||0;tx.update(myRef,{lastCommentAt:now,commentCount:mine+1})}else tx.set(myRef,{threadKey:key,questionId:q.id,firstCommentAt:now,lastCommentAt:now,commentCount:1})});discussionReplyTarget=null}
async function deleteDiscussionComment(qid,commentId){if(!firebaseDiscussionReady())throw new Error('Discussion service is not connected.');const key=discussionThreadKey(qid),ref=discussionDb.collection('discussions').doc(key).collection('comments').doc(commentId),FV=window.firebase.firestore.FieldValue;await ref.update({text:'',deleted:true,deletedAt:FV.serverTimestamp()})}
async function reportDiscussionComment(qid,commentId){if(!firebaseDiscussionReady())throw new Error('Discussion service is not connected.');let reason=prompt('Report reason: incorrect, inappropriate, spam, or other','incorrect');if(reason===null)return;reason=String(reason).trim().toLowerCase();if(!['incorrect','inappropriate','spam','other'].includes(reason)){alert('Use one of: incorrect, inappropriate, spam, other.');return}let detail='';if(reason==='other'){const x=prompt('Briefly describe the concern (optional, maximum 500 characters):','');if(x===null)return;detail=String(x).trim().slice(0,500)}const FV=window.firebase.firestore.FieldValue;await discussionDb.collection('reports').add({reporterUid:currentDiscussionUid,threadKey:discussionThreadKey(qid),commentId,reason,detail,createdAt:FV.serverTimestamp(),status:'open'});alert('Report submitted. Thank you.')}
async function runDiscussionAction(task,button){if(button)button.disabled=true;try{await task()}catch(err){alert(friendlyFirebaseError(err))}finally{if(button&&button.isConnected)button.disabled=false}}
function bindDiscussionSurfaces(){bindDiscussionActions(app);syncDiscussionCommentSubscriptions()}
function searchMatch(q,term){if(!term)return false;const base=[q.stem,q.topic,q.source,q.abaKeyword,q.domain,q.level].filter(Boolean).join(' ').toLowerCase();if(base.includes(term))return true;if(searchIncludeExplanations&&searchIndexMap)return String(searchIndexMap.get(Number(q.id))||'').toLowerCase().includes(term);return false}
function searchResultsHTML(){const term=searchQuery.trim().toLowerCase();if(!term)return `<div class="search-empty">Type a word, phrase, topic, source or ABA keyword to search all ${QUESTIONS.length} questions.</div>`;const all=QUESTIONS.filter(q=>searchMatch(q,term));const shown=all.slice(0,60);return `<div class="search-count"><strong>${all.length}</strong> result${all.length===1?'':'s'}${all.length>shown.length?` · showing first ${shown.length}`:''}</div>${shown.length?`<div class="search-results">${shown.map(q=>`<button class="search-result" data-action="open-search-question" data-qid="${q.id}"><span class="search-result-meta">${esc(q.topic)} · ${esc(q.source)} · ${esc(sourceQLabel(q))}</span><span class="search-result-stem">${q.stemHtml||esc(q.stem)}</span>${q.abaKeyword?`<small>ABA keyword: ${esc(q.abaKeyword)}</small>`:''}</button>`).join('')}</div>`:`<div class="search-empty">No matching questions. Try fewer or broader terms.</div>`}`}
function searchPage(){return shell(`<section class="page-heading search-page"><div class="page-width"><p class="eyebrow">Global search</p><h1>Search the question bank</h1><p>Search question stems, topics, original sources and ABA keywords. Explanation text can be included on demand.</p><div class="global-search-box"><label for="global-search-input">Search</label><input id="global-search-input" type="search" inputmode="search" autocomplete="off" placeholder="e.g. P50, propofol, renal failure…" value="${esc(searchQuery)}"><label class="search-explanation-toggle"><input id="search-include-explanations" type="checkbox" ${searchIncludeExplanations?'checked':''}> <span>Include explanations and references</span></label></div><div id="search-results-region" aria-live="polite">${searchResultsHTML()}</div></div></section>`,'search')}
function bindSearchControls(){const input=document.getElementById('global-search-input'),results=document.getElementById('search-results-region'),toggle=document.getElementById('search-include-explanations');if(input&&results){input.addEventListener('input',()=>{searchQuery=input.value;results.innerHTML=searchResultsHTML();bindSearchResultButtons(results)});requestAnimationFrame(()=>input.focus({preventScroll:true}))}if(toggle&&results)toggle.addEventListener('change',async()=>{searchIncludeExplanations=toggle.checked;if(toggle.checked&&!searchIndexMap){toggle.disabled=true;results.innerHTML='<div class="search-empty">Loading explanation index…</div>';try{await ensureSearchIndex()}catch(err){alert(err?.message||err);toggle.checked=false;searchIncludeExplanations=false}finally{toggle.disabled=false}}results.innerHTML=searchResultsHTML();bindSearchResultButtons(results)})}
function bindSearchResultButtons(root=document){root.querySelectorAll('[data-action="open-search-question"]').forEach(el=>{if(el.dataset.actionBound==='1')return;el.dataset.actionBound='1';el.addEventListener('click',handleAction)})}
function home(){const sources=getSourceGroups();const autosave=readAutosave();const review=reviewQueueStats();const resume=autosave&&!autosave.submitted?`<div class="page-width"><div class="card autosave-card"><div class="autosave-card-copy"><h3>Autosaved Session</h3><p>${esc(autosave.title||'Unfinished session')} · saved ${esc(fmtDate(autosave.savedAt))}</p><button class="text-link" data-route="saved">[See other saved sessions]</button></div><div class="autosave-actions"><button class="primary-button" data-action="resume-autosave">Resume session</button><button class="secondary-button" data-action="discard-autosave">Discard autosave</button></div></div></div>`:'';return shell(`<section class="hero"><div class="page-width"><div class="ayah-block"><p>“In the name of Allah, the Most Gracious, the Most Merciful” <cite>(Al-Quran 1:1)</cite></p><p>“They said, ‘Glory be to You! We have no knowledge except what You have taught us. You are truly the All-Knowing, All-Wise.’” <cite>(Al-Quran 2:32)</cite></p></div><div class="hero-copy"><p class="eyebrow">Primary Anaesthesia Revision</p><h1>Primary FRCA sciences, built for deliberate practice.</h1><div class="hero-stats"><span><strong>${QUESTIONS.length}</strong> questions</span><span><strong>${getTopics().length}</strong> topics</span><span><strong>${sources.length}</strong> original sources</span></div></div></div></section>${resume}<section class="section"><div class="page-width"><div class="mode-grid"><button class="mode-card" data-route="topics"><h3>Study by Topic</h3><p>Work through focused topic sets in Study, Test Yourself or Timed mode.</p><span class="arrow">Choose a topic →</span></button><button class="mode-card mock" data-route="mock"><h3>Mock Exam</h3><p>Build a mixed assessment across the available Primary FRCA domains and source levels.</p><span class="arrow">Build a mock →</span></button><button class="mode-card sources" data-route="sources"><h3>Original Sources</h3><p>Revise every supplied source collection in its original SBA question order.</p><span class="arrow">Browse source sets →</span></button><button class="mode-card review ${review.count?'':'empty'}" data-action="review-queue"><span class="review-count">${review.count} to review</span><h3>Review Questions</h3><p>${review.count?`${review.incorrect} incorrect · ${review.unanswered} unanswered · ${review.flagged} flagged`:'Flagged and previously incorrect or unanswered questions will collect here automatically.'}</p><span class="arrow">${review.count?'Start review →':'Ready when you need it'}</span></button></div><button class="discussion-home-card" data-route="discussions"><span><h3>Discussions</h3><p>Browse shared question discussions, comments and replies from other candidates.</p></span><span class="arrow">Browse discussions →</span></button></div></section>${performanceDashboard()}`,'')}function savedSessionsPage(){const records=savedSessionRecords();return shell(`<section class="page-heading"><div class="page-width"><p class="eyebrow">Saved sessions</p><h1>Continue where you left off</h1><p>Your current autosave and persistent Study-mode sessions are kept on this device. Study sessions remain available even after you work in another set.</p>${records.length?`<div class="saved-list">${records.map(r=>{const d=r.draft,answered=Object.keys(d.answers||{}).length,revealed=(d.revealedIds||[]).length,label=r.type==='autosave'?'Current autosave':'Saved Study session';return `<div class="saved-card"><div><h3>${esc(d.title||'Saved session')}</h3><p>${esc(d.subtitle||'')} · ${esc(d.mode==='study'?'Study':d.mode==='timed'?'Timed':'Test')} · ${d.questionIds.length} questions</p><small>${label} · ${answered} answered · ${revealed} revealed · saved ${esc(fmtDate(d.savedAt))}</small></div><div class="saved-actions">${r.type==='autosave'?`<button class="primary-button" data-action="resume-autosave">Resume</button><button class="secondary-button" data-action="discard-autosave">Discard</button>`:`<button class="primary-button" data-action="resume-saved-study" data-study-key="${esc(r.key)}">Continue</button><button class="secondary-button" data-action="discard-saved-study" data-study-key="${esc(r.key)}">Remove</button>`}</div></div>`}).join('')}</div>`:`<div class="saved-empty">No saved sessions yet. Start a Study set or leave an assessment unfinished and it will appear here.</div>`}</div></section>`,'saved')}
function topicsPage(){const topics=getTopics().filter(t=>topicFilter==='All'||t.domain===topicFilter);const filters=['All',...getDomains()];return shell(`<section class="page-heading"><div class="page-width"><p class="eyebrow">Study by Topic</p><h1>Choose a topic</h1><p>Each topic is divided into sets of up to ${SET_SIZE} questions. Study progress is saved independently for every Study-mode set.</p><div class="filter-row">${filters.map(f=>`<button class="${topicFilter===f?'active':''}" data-topic-filter="${esc(f)}">${esc(f)}</button>`).join('')}</div><div class="topic-grid">${topics.map(t=>{const p=getProgress(),seen=t.questions.filter(q=>(getHistory(q.id,p).studyChecks||0)+(getHistory(q.id,p).assessmentAttempts||0)>0).length;return `<button class="topic-card" data-topic="${esc(t.name)}"><h3>${esc(t.name)}</h3><p>${esc(t.domain)}</p><div class="meta"><span>${t.questions.length} questions · ${Math.ceil(t.questions.length/SET_SIZE)} set${Math.ceil(t.questions.length/SET_SIZE)===1?'':'s'}</span><span>${seen} seen</span></div></button>`}).join('')}</div></div></section>`,'topics')}
function setCardHTML(items,label,keyBase,meta){const ids=items.map(q=>q.id);const p=getProgress(),seen=ids.filter(id=>(getHistory(id,p).studyChecks||0)+(getHistory(id,p).assessmentAttempts||0)>0).length;const studyKey=`${keyBase}`;const saved=readStudySnapshot(studyKey);return `<div class="set-card" data-set-card data-question-ids="${ids.join(',')}" data-study-key="${esc(studyKey)}" data-kind="${esc(meta.kind)}" data-title="${esc(meta.title)}" data-subtitle="${esc(label)}"><div class="set-head"><div><h3>${esc(label)}</h3><p>${items.length} questions</p></div><span class="set-progress">${seen}/${items.length} seen</span></div>${saved?`<div class="resume-study-note">Study progress saved ${esc(fmtDate(saved.savedAt))}. Continue with your selected answers, checked answers, revealed explanations and question position intact.</div>`:''}<div class="mode-choice-grid"><label class="mode-choice"><input type="radio" name="mode-${esc(studyKey)}" value="study" checked><span>Study</span></label><label class="mode-choice"><input type="radio" name="mode-${esc(studyKey)}" value="test"><span>Test Yourself</span></label><label class="mode-choice"><input type="radio" name="mode-${esc(studyKey)}" value="timed"><span>Timed</span></label></div><div class="timed-settings" hidden><label>Timer <select data-timer-minutes><option value="20">20 min</option><option value="30">30 min</option><option value="45">45 min</option><option value="60" selected>60 min</option><option value="90">90 min</option></select></label></div><div class="set-actions">${saved?`<button class="primary-button" data-action="continue-study">Continue where you left off</button><button class="secondary-button" data-action="start-set">Start new study session</button>`:`<button class="primary-button" data-action="start-set">Start study mode</button>`}</div></div>`}
function topicDetail(name){const t=getTopics().find(x=>x.name===name);if(!t)return topicsPage();const sets=chunks(t.questions);return shell(`<section class="page-heading"><div class="page-width"><button class="secondary-button" data-route="topics">← Topics</button><p class="eyebrow" style="margin-top:18px">${esc(t.domain)}</p><h1>${esc(t.name)}</h1><p>${t.questions.length} questions across ${sets.length} set${sets.length===1?'':'s'}. Select a mode, then explicitly start it.</p><div class="set-grid" style="margin-top:22px">${sets.map((items,i)=>setCardHTML(items,`Set ${i+1}`,`topic:${t.name}:${i+1}`,{kind:'topic',title:t.name})).join('')}</div></div></section>`,'topics')}
function sourcesPage(){return shell(`<section class="page-heading"><div class="page-width"><p class="eyebrow">Original sources</p><h1>Revise in source order</h1><p>Each source is divided into sets of up to ${SET_SIZE} questions. Study-mode progress is persistent per source set.</p><div class="source-grid" style="margin-top:22px">${getSourceGroups().map(s=>`<button class="source-card" data-source="${s.code}"><h3>${esc(s.name)}</h3><p>${esc(s.level)} · ${esc(s.domain)}</p><div class="meta"><span>${s.questions.length} questions</span><span>${Math.ceil(s.questions.length/SET_SIZE)} sets</span></div></button>`).join('')}</div></div></section>`,'sources')}
function sourceDetail(code){const s=getSourceGroups().find(x=>x.code===code);if(!s)return sourcesPage();const sets=groupSourceSets(s.questions);return shell(`<section class="page-heading"><div class="page-width"><button class="secondary-button" data-route="sources">← Sources</button><p class="eyebrow" style="margin-top:18px">${esc(s.level)} · ${esc(s.domain)}</p><h1>${esc(s.name)}</h1><p>${s.questions.length} SBA questions in original source order.</p><div class="set-grid" style="margin-top:22px">${sets.map((g,i)=>{const first=g.questions[0],last=g.questions.at(-1);const range=g.questions.length>1?`${sourceQLabel(first)}–${sourceQLabel(last).replace(/^.*? Q/i,'Q')}`:sourceQLabel(first);const label=g.label&&g.label!=='Questions'?`${g.label} · ${range}`:range;return setCardHTML(g.questions,label,`source:${s.code}:${i+1}`,{kind:'source',title:s.name})}).join('')}</div></div></section>`,'sources')}
function mockPage(){const domains=getDomains(),levels=getLevels();return shell(`<section class="page-heading"><div class="page-width"><p class="eyebrow">Mock exam</p><h1>Build a mixed Primary mock</h1><p>Assessment results contribute to readiness statistics. Choose the mix you want; the timer is optional.</p><div class="card" style="margin-top:22px"><div class="mock-builder-v2"><div class="mock-row"><div class="mock-control-v2"><label for="mock-count">Questions <output id="mock-count-output">50</output></label><input class="range-control" id="mock-count" type="range" min="10" max="100" step="10" value="50"></div><div class="mock-control-v2"><span class="control-label">Question order</span><div class="chip-row"><label class="check-chip"><input id="mock-shuffle" type="checkbox" checked><span>Randomise</span></label></div><p class="mock-helper">Turn off Randomise to keep the filtered questions in source order.</p></div></div><div class="mock-row"><div class="mock-control-v2"><span class="control-label">Domain <small>select any combination</small></span><div class="chip-row">${domains.map(d=>`<label class="check-chip"><input type="checkbox" data-mock-domain value="${esc(d)}" checked><span>${esc(d)}</span></label>`).join('')}</div></div><div class="mock-control-v2"><span class="control-label">Level <small>select any combination</small></span><div class="chip-row">${levels.map(l=>`<label class="check-chip"><input type="checkbox" data-mock-level value="${esc(l)}" checked><span>${esc(l)}</span></label>`).join('')}</div></div></div><div class="mock-control-v2"><span class="control-label">Timer</span><div class="chip-row"><label class="check-chip"><input id="mock-use-timer" type="checkbox"><span>Use timer</span></label></div><div class="mock-timer-settings" id="mock-timer-settings" hidden><label for="mock-minutes" style="display:flex;justify-content:space-between;margin-top:10px;color:var(--muted);font-size:10px;font-weight:800">Duration <output id="mock-minutes-output">60 min</output></label><input class="range-control" id="mock-minutes" type="range" min="20" max="180" step="5" value="60"></div></div></div><button class="primary-button" data-action="start-mock">Generate mock exam</button></div></div></section>`,'mock')}
async function startSession({kind,mode,title,subtitle,questionIds,studyKey='',durationMinutes=null,meta={}}){app.innerHTML=appLoading('Loading selected questions…');try{await ensureQuestionDetails(questionIds)}catch(err){alert(err?.message||err);render();return}activeSession={id:(globalThis.crypto?.randomUUID?.()||('pr-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12))),kind,mode,title,subtitle,questionIds:[...questionIds],answers:{},revealedIds:new Set(),expandedIds:new Set(),recordedIds:new Set(),viewMode:'continuous',currentIndex:0,deadline:mode==='timed'||kind==='mock'&&durationMinutes?Date.now()+durationMinutes*60000:null,durationMinutes,studyKey,meta,submitted:false};clearAutosave();saveAutosave('start');navigate('session')}
async function resumeDraft(d){activeSession=draftToSession(d);if(!activeSession)return;app.innerHTML=appLoading('Restoring saved session…');try{await ensureQuestionDetails(activeSession.questionIds)}catch(err){alert(err?.message||err);activeSession=null;render();return}navigate('session')}
async function continueStudy(key){const d=readStudySnapshot(key);if(!d)return;activeSession=draftToSession(d);activeSession.submitted=false;app.innerHTML=appLoading('Restoring study session…');try{await ensureQuestionDetails(activeSession.questionIds)}catch(err){alert(err?.message||err);activeSession=null;render();return}saveAutosave('continue-study');navigate('session')}
async function startFromSet(card){const ids=card.dataset.questionIds.split(',').map(Number),studyKey=card.dataset.studyKey,kind=card.dataset.kind,title=card.dataset.title,subtitle=card.dataset.subtitle;const mode=card.querySelector('input[type=radio]:checked')?.value||'study';const mins=mode==='timed'?Number(card.querySelector('[data-timer-minutes]').value):null;if(mode==='study')deleteStudySnapshot(studyKey);await startSession({kind,mode,title,subtitle,questionIds:ids,studyKey:mode==='study'?studyKey:'',durationMinutes:mins,meta:{}})}
function visualHTML(q,component){const assets=component==='question'?q.questionImages:q.answerImages;if(assets?.length)return assets.map((a,i)=>{const alt=`${a.label||((component==='question'?'Question':'Explanation')+' figure')} from ${q.source} page ${a.page}`;return `<figure class="source-visual-block"><button type="button" class="visual-zoom-button" data-figure-src="${esc(a.src)}" data-figure-alt="${esc(alt)}" aria-label="Open figure full screen"><img class="visual-image" src="${esc(a.src)}" alt="${esc(alt)}" loading="lazy"><span class="visual-zoom-label">Tap to enlarge</span></button><figcaption class="source-visual-caption">${esc(a.label||((component==='question'?'Question':'Explanation')+' figure'))} · source PDF p.${a.page}</figcaption></figure>`}).join('');return''}
function optionHTML(q,key,text,s){const ans=s.answers[q.id],revealed=s.revealedIds.has(q.id)||s.submitted;let cls=ans===key?'selected':'';if(revealed){if(key===q.correctAnswer)cls+=' correct';else if(ans===key&&key!==q.correctAnswer)cls+=' incorrect'}const item=q.options.find(o=>o.key===key),rich=item?.html||esc(text);return `<label class="option ${cls.trim()}" data-qid="${q.id}" data-key="${key}"><input type="radio" name="q-${q.id}" value="${key}" ${ans===key?'checked':''} ${s.submitted?'disabled':''}><span class="option-key">${key}</span><span class="option-text">${rich}</span></label>`}
function explanationHTML(q,s){if(!s.expandedIds.has(q.id)&&!s.submitted)return'';const correctText=q.correctAnswerText||((q.options.find(o=>o.key===q.correctAnswer)||{}).text||'');return `<div class="explanation-panel"><p class="source-label">Explanation reproduced from the source</p><p class="source-answer-title">Original source answer</p><p class="source-caveat">The original source explanation is reproduced from PDF text extraction. Its matching and transcription were automated and must be checked against the cited PDF pages before clinical or examination use.</p><div class="correct-answer-line"><span>Correct answer</span><strong>${esc(q.correctAnswer)}${correctText?'. '+esc(correctText):''}</strong></div>${q.sourceAnswerNote?`<div class="source-answer-note"><strong>Source note:</strong> ${esc(q.sourceAnswerNote)}</div>`:''}${visualHTML(q,'answer')}<div class="explanation-section"><h4>Explanation</h4><div class="explanation-prose">${q.explanationHtml||`<p>${esc(q.explanation)}</p>`}</div>${tableHTML(q,'answer')}</div>${q.rationales?`<div class="explanation-section"><h4>Answer rationale(s)</h4>${q.rationalesHtml||`<div class="explanation-prose"><p>${esc(q.rationales)}</p></div>`}</div>`:''}${q.bottomLine?`<div class="explanation-section bottom-line"><h4>Bottom Line</h4><div class="explanation-prose">${q.bottomLineHtml||`<p>${esc(q.bottomLine)}</p>`}</div></div>`:''}${q.trueLearnInsight?`<div class="explanation-section insight"><h4>TrueLearn Insight</h4><div class="explanation-prose">${q.trueLearnInsightHtml||`<p>${esc(q.trueLearnInsight)}</p>`}</div></div>`:''}<div class="explanation-section references"><div class="source-section-heading"><h4>Source</h4><button class="source-page-button" data-action="view-source" data-qid="${q.id}">View source page</button></div><p>${esc(q.source)} · ${esc(sourceQLabel(q))} · Question p.${q.questionPage} · Answer p.${q.answerPageStart}${q.answerPageEnd&&q.answerPageEnd!==q.answerPageStart?'–'+q.answerPageEnd:''}${q.abaKeyword?` · Keyword: ${esc(q.abaKeyword)}`:''}</p>${q.references?`<div class="explanation-prose references-list-wrap" style="margin-top:6px">${q.referencesHtml||`<p>${esc(q.references)}</p>`}</div>`:''}</div></div>`}
function cardHTML(q,index,s){const ans=s.answers[q.id],revealed=s.revealedIds.has(q.id)||s.submitted;let fb='';if(revealed){if(!ans)fb=`<div class="feedback neutral">Unanswered · Correct answer: ${q.correctAnswer}</div>`;else if(ans===q.correctAnswer)fb=`<div class="feedback good">Correct · ${q.correctAnswer}</div>`;else fb=`<div class="feedback bad">Incorrect · Correct answer: ${q.correctAnswer}</div>`}const p=getProgress();const flagged=Boolean(p.flags[q.id]);return `<article class="question-card ${s.viewMode==='one'&&index===s.currentIndex?'current-card':''}" id="question-${q.id}" ${s.viewMode==='one'&&index!==s.currentIndex?'hidden':''}><div class="q-meta"><span>${index+1}/${s.questionIds.length} · ${esc(sourceLabel(q))}</span><button class="flag-button ${flagged?'flagged':''}" data-action="flag" data-qid="${q.id}">${flagged?'★ Flagged':'☆ Flag'}</button></div><div class="question-stem">${q.stemHtml||esc(q.stem)}</div>${visualHTML(q,'question')}${tableHTML(q,'question')}<div class="options">${q.options.map(o=>optionHTML(q,o.key,o.text,s)).join('')}</div><div class="q-actions">${s.mode==='study'&&!revealed?`<button class="primary-button" data-action="check-answer" data-qid="${q.id}" ${ans?'':'disabled'}>Check answer</button>`:''}${revealed&&!s.expandedIds.has(q.id)?`<button class="secondary-button" data-action="show-explanation" data-qid="${q.id}">Show explanation</button>`:''}${s.expandedIds.has(q.id)&&!s.submitted?`<button class="secondary-button" data-action="hide-explanation" data-qid="${q.id}">Hide explanation</button>`:''}</div>${fb}${explanationHTML(q,s)}${(s.expandedIds.has(q.id)||s.submitted)?discussionPanelHTML(q):''}</article>`}
function navHTML(s){const navTimer=s.deadline&&!s.submitted?`<span class="nav-timer" id="nav-timer">--:--</span>`:'';return `<aside class="question-nav ${s.viewMode==='one'?'one':''}" id="question-nav"><div class="nav-top"><strong>Question navigator</strong>${navTimer}<button class="navigator-toggle" data-action="toggle-nav" aria-expanded="false">Open ▴</button></div><div class="question-view-control"><button class="${s.viewMode==='continuous'?'active':''}" data-view="continuous">Continuous</button><button class="${s.viewMode==='one'?'active':''}" data-view="one">One by one</button></div><div class="question-palette">${s.questionIds.map((id,i)=>{const answered=Boolean(s.answers[id]),revealed=s.revealedIds.has(id),flagged=getProgress().flags[id],current=s.viewMode==='one'&&i===s.currentIndex;return `<button class="${answered?'answered ':''}${revealed?'revealed ':''}${flagged?'flagged ':''}${current?'current':''}" data-palette-index="${i}">${i+1}</button>`}).join('')}</div><div class="step-controls"><button data-action="prev-question" aria-label="Previous question" ${s.currentIndex<=0?'disabled':''}>‹</button><span>${s.currentIndex+1} / ${s.questionIds.length}</span><button data-action="next-question" aria-label="Next question" ${s.currentIndex>=s.questionIds.length-1?'disabled':''}>›</button><button class="step-nav-expand" data-action="toggle-nav" aria-label="Expand question navigator" aria-expanded="false">⌃</button></div>${s.mode!=='study'&&!s.submitted?`<button class="primary-button submit-session" data-action="submit-session">Submit ${s.kind==='mock'?'mock':'assessment'}</button>`:''}</aside>`}
function sessionPage(){if(!activeSession){const d=readAutosave();activeSession=draftToSession(d);if(!activeSession)return home()}const s=activeSession;const qs=s.questionIds.map(questionById).filter(Boolean);const timer=s.deadline?`<span class="timer-chip" id="timer-chip">--:--</span>`:'';const result=s.submitted?resultHTML(s):'';const bottomSubmit=s.viewMode==='continuous'&&!s.submitted&&s.mode!=='study'&&(s.kind==='mock'||s.mode==='timed')?`<div class="continuous-submit-wrap"><button class="primary-button" data-action="submit-session">Submit ${s.kind==='mock'?'mock':'timed assessment'}</button><small>End of question set</small></div>`:'';const content=`<section class="session-page ${s.viewMode==='one'?'one-by-one-view':''}"><div class="page-width"><div class="session-heading"><div><p class="eyebrow">${esc(s.mode==='study'?'Study mode':s.mode==='timed'?'Timed assessment':s.kind==='mock'?'Mock exam':'Test Yourself')}</p><h1>${esc(s.title)}</h1><p>${esc(s.subtitle||'')} · ${s.questionIds.length} questions</p></div><div class="session-tools">${timer}<span class="autosave-indicator" id="autosave-indicator">Autosave on</span><button class="secondary-button" data-action="exit-session">Exit session</button></div></div>${result}<div class="session-layout"><div class="question-list">${qs.map((q,i)=>cardHTML(q,i,s)).join('')}${bottomSubmit}</div>${navHTML(s)}</div></div></section>`;setTimeout(startRuntimeHooks,0);return shell(content,'')}
function resultHTML(s){const qs=s.questionIds.map(questionById);let correct=0;qs.forEach(q=>{if(s.answers[q.id]===q.correctAnswer)correct++});const pct=Math.round(correct/qs.length*100);return `<div class="result-card"><span class="result-score">${pct}%</span><h2>${correct} / ${qs.length} correct</h2><p>Assessment submitted. Explanations are now available on every question.</p></div>`}
function startRuntimeHooks(){stopTimer();if(activeSession?.deadline&&!activeSession.submitted){updateTimer();timerHandle=setInterval(updateTimer,1000)}updateAutosaveIndicator();syncMobileMenu()}
function stopTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null}}
function updateTimer(){if(!activeSession?.deadline)return;const left=Math.max(0,activeSession.deadline-Date.now()),sec=Math.ceil(left/1000),m=Math.floor(sec/60),ss=sec%60,text=`${m}:${String(ss).padStart(2,'0')}`,warning=left<5*60000;['timer-chip','nav-timer'].forEach(id=>{const el=document.getElementById(id);if(el){el.textContent=text;el.classList.toggle('warning',warning)}});if(left<=0&&!activeSession.submitted)submitSession(true)}
function updateAutosaveIndicator(){const el=document.getElementById('autosave-indicator');if(el)el.textContent='Saved just now'}
function render(){stopTimer();if(!bankReady){app.innerHTML=appLoading(bankLoadError?'Question bank could not be loaded':'Loading question index…');return}let content='';if(routeState.name==='home')content=home();else if(routeState.name==='topics')content=topicsPage();else if(routeState.name==='topic')content=topicDetail(routeState.params.name);else if(routeState.name==='sources')content=sourcesPage();else if(routeState.name==='source')content=sourceDetail(routeState.params.code);else if(routeState.name==='mock')content=mockPage();else if(routeState.name==='saved')content=savedSessionsPage();else if(routeState.name==='search')content=searchPage();else if(routeState.name==='discussions')content=discussionsPage();else if(routeState.name==='discussion')content=discussionDetailPage(routeState.params.id);else if(routeState.name==='session')content=sessionPage();else content=home();app.innerHTML=content;bindUI();syncMobileMenu()}
function bindUI(){app.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.route)));app.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>navigate('topic',{name:b.dataset.topic})));app.querySelectorAll('[data-source]').forEach(b=>b.addEventListener('click',()=>navigate('source',{code:b.dataset.source})));app.querySelectorAll('[data-topic-filter]').forEach(b=>b.addEventListener('click',()=>{topicFilter=b.dataset.topicFilter;render()}));app.querySelectorAll('[data-set-card]').forEach(card=>{card.querySelectorAll('input[type=radio]').forEach(r=>r.addEventListener('change',()=>updateSetCard(card)));updateSetCard(card)});app.querySelectorAll('[data-action]').forEach(el=>{el.dataset.actionBound='1';el.addEventListener('click',handleAction)});app.querySelectorAll('.option').forEach(el=>el.addEventListener('click',handleOption));app.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>{if(!activeSession)return;if(el.dataset.view==='one'&&activeSession.viewMode!=='one'){activeSession.currentIndex=currentVisibleIndex()}activeSession.viewMode=el.dataset.view==='one'?'one':'continuous';saveAutosave('view-mode');render()}));app.querySelectorAll('[data-palette-index]').forEach(el=>el.addEventListener('click',()=>paletteGo(Number(el.dataset.paletteIndex))));app.querySelectorAll('[data-discussion-question]').forEach(el=>el.addEventListener('click',()=>navigate('discussion',{id:Number(el.dataset.discussionQuestion)})));app.querySelectorAll('[data-discussion-view]').forEach(el=>el.addEventListener('click',()=>{discussionView=el.dataset.discussionView;render()}));app.querySelectorAll('[data-discussion-scope]').forEach(el=>el.addEventListener('click',()=>{discussionScope=el.dataset.discussionScope;render()}));bindMockControls();bindSearchControls();bindSearchResultButtons(app);app.querySelectorAll('[data-figure-src]').forEach(el=>el.addEventListener('click',()=>openFigureLightbox(el.dataset.figureSrc,el.dataset.figureAlt||'Source figure')));const importFile=document.getElementById('progress-import-file');if(importFile)importFile.addEventListener('change',e=>{const file=e.target.files?.[0];if(file)importProgressFile(file);e.target.value=''});bindDiscussionSurfaces()}
function bindMockControls(){const count=document.getElementById('mock-count'),countOut=document.getElementById('mock-count-output'),useTimer=document.getElementById('mock-use-timer'),timerBox=document.getElementById('mock-timer-settings'),mins=document.getElementById('mock-minutes'),minsOut=document.getElementById('mock-minutes-output');if(count&&countOut){const sync=()=>countOut.textContent=count.value;count.addEventListener('input',sync);sync()}if(useTimer&&timerBox){const sync=()=>{timerBox.hidden=!useTimer.checked};useTimer.addEventListener('change',sync);sync()}if(mins&&minsOut){const sync=()=>minsOut.textContent=`${mins.value} min`;mins.addEventListener('input',sync);sync()}}
function exportProgress(){const payload={app:'Primary Revision',format:'primary-revision-progress',version:1,exportedAt:new Date().toISOString(),questionBankSize:QUESTIONS.length,progress:getProgress(),studySessions:getStudyStore(),autosave:readAutosave()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a'),date=new Date().toISOString().slice(0,10);a.href=url;a.download=`Primary_Revision_Progress_${date}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}
function importProgressFile(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(String(reader.result||''));if(data?.format!=='primary-revision-progress'||!data.progress)throw new Error('Not a Primary Revision progress export');if(!confirm('Import this progress file? Current progress, saved Study sessions and autosave on this device will be replaced.'))return;saveJSON(KEYS.progress,data.progress);saveJSON(KEYS.study,data.studySessions||{});if(data.autosave)saveJSON(KEYS.autosave,data.autosave);else localStorage.removeItem(KEYS.autosave);activeSession=null;alert('Progress imported successfully.');navigate('home')}catch(err){alert(`Could not import progress: ${err.message||err}`)}};reader.readAsText(file)}
function updateSetCard(card){const mode=card.querySelector('input[type=radio]:checked')?.value||'study';card.querySelector('.timed-settings').hidden=mode!=='timed';const saved=studySnapshotExists(card.dataset.studyKey);const actions=card.querySelector('.set-actions');if(mode==='study'&&saved)actions.innerHTML='<button class="primary-button" data-action="continue-study">Continue where you left off</button><button class="secondary-button" data-action="start-set">Start new study session</button>';else actions.innerHTML=`<button class="primary-button" data-action="start-set">Start ${mode==='study'?'study mode':mode==='test'?'Test Yourself':'timed mode'}</button>`;actions.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',handleAction))}
function handleOption(e){if(!activeSession||activeSession.submitted)return;const opt=e.currentTarget,qid=Number(opt.dataset.qid),key=opt.dataset.key;if(activeSession.mode==='study'&&activeSession.revealedIds.has(qid))return;activeSession.answers[qid]=key;saveAutosave('answer');updateCardSelection(qid)}
function updateCardSelection(qid){const card=document.getElementById(`question-${qid}`);if(!card)return;card.querySelectorAll('.option').forEach(o=>{const selected=activeSession.answers[qid]===o.dataset.key;o.classList.toggle('selected',selected);const input=o.querySelector('input');if(input)input.checked=selected});const btn=card.querySelector('[data-action="check-answer"]');if(btn)btn.disabled=!activeSession.answers[qid];updateNavigatorClasses()}
function recordStudyCheck(q){if(activeSession.recordedIds.has(q.id))return;activeSession.recordedIds.add(q.id);const p=getProgress(),h=getHistory(q.id,p),isCorrect=activeSession.answers[q.id]===q.correctAnswer;h.studyChecks=(h.studyChecks||0)+1;if(isCorrect)h.studyCorrect=(h.studyCorrect||0)+1;h.lastStudyCorrect=isCorrect;h.needsReview=!isCorrect;p.questionHistory[q.id]=h;setProgress(p)}
function checkAnswer(qid){const q=questionById(qid);if(!q||!activeSession.answers[qid])return;activeSession.revealedIds.add(qid);recordStudyCheck(q);saveAutosave('check-answer');renderSessionPreserveScroll(qid)}
function renderSessionPreserveScroll(qid){const card=document.getElementById(`question-${qid}`);const top=card?card.getBoundingClientRect().top:null;render();if(top!==null&&activeSession.viewMode==='continuous'){requestAnimationFrame(()=>{const nc=document.getElementById(`question-${qid}`);if(nc){const delta=nc.getBoundingClientRect().top-top;window.scrollBy(0,delta)}})}}
function submitSession(timeout=false){if(!activeSession||activeSession.submitted)return;const unansweredIds=activeSession.questionIds.filter(id=>!activeSession.answers[id]);if(!timeout&&(activeSession.kind==='mock'||activeSession.mode==='timed')&&unansweredIds.length){const noun=unansweredIds.length===1?'question is':'questions are';if(!confirm(`${unansweredIds.length} ${noun} unanswered. Unanswered questions will be counted as wrong when you submit. Submit anyway?`))return}activeSession.submitted=true;activeSession.questionIds.forEach(id=>activeSession.revealedIds.add(id));const p=getProgress();let correct=0;activeSession.questionIds.forEach(id=>{const q=questionById(id),ans=activeSession.answers[id],h=getHistory(id,p);h.assessmentAttempts=(h.assessmentAttempts||0)+1;h.lastAssessmentAnswered=Boolean(ans);h.lastAssessmentCorrect=Boolean(ans&&ans===q.correctAnswer);h.needsReview=!h.lastAssessmentCorrect;if(h.lastAssessmentCorrect){h.assessmentCorrect=(h.assessmentCorrect||0)+1;correct++}p.questionHistory[id]=h});const pct=Math.round(correct/activeSession.questionIds.length*100);p.assessments.push({id:activeSession.id,kind:activeSession.kind,mode:activeSession.mode,title:activeSession.title,questionIds:[...activeSession.questionIds],correct,total:activeSession.questionIds.length,pct,completed:true,finishedAt:Date.now(),timeout});setProgress(p);clearAutosave();if(activeSession.studyKey)deleteStudySnapshot(activeSession.studyKey);render()}
function currentVisibleIndex(){if(!activeSession)return 0;const cards=[...document.querySelectorAll('.question-card')];const header=document.querySelector('.site-header')?.getBoundingClientRect().height||0;let best=0,bestDist=Infinity;cards.forEach((c,i)=>{if(c.hidden)return;const d=Math.abs(c.getBoundingClientRect().top-header-10);if(d<bestDist){bestDist=d;best=i}});return best}
function moveQuestion(delta){if(!activeSession)return;activeSession.currentIndex=Math.max(0,Math.min(activeSession.questionIds.length-1,activeSession.currentIndex+delta));saveAutosave('question-position');render();if(activeSession.viewMode==='one')requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:'auto'}))}
function paletteGo(i){if(!activeSession)return;if(activeSession.viewMode==='one'){activeSession.currentIndex=i;saveAutosave('question-position');render()}else{document.getElementById(`question-${activeSession.questionIds[i]}`)?.scrollIntoView({behavior:'smooth',block:'start'})}}
function updateNavigatorClasses(){if(!activeSession)return;document.querySelectorAll('[data-palette-index]').forEach((b,i)=>{const id=activeSession.questionIds[i];b.classList.toggle('answered',Boolean(activeSession.answers[id]));b.classList.toggle('revealed',activeSession.revealedIds.has(id));b.classList.toggle('flagged',Boolean(getProgress().flags[id]))})}
function reviewQueue(){const stats=reviewQueueStats();if(!stats.count){alert('Nothing to review yet. Questions you flag, answer incorrectly, or leave unanswered in an assessment will appear here automatically.');return}startSession({kind:'review',mode:'study',title:'Review Questions',subtitle:'Flagged, incorrect and unanswered questions',questionIds:stats.ids,studyKey:'',durationMinutes:null})}

function closePrimaryModal(){document.getElementById('primary-runtime-modal')?.remove()}
function openSourceModal(qid){const q=questionById(qid);if(!q)return;closePrimaryModal();const answerRange=q.answerPageStart?(q.answerPageEnd&&q.answerPageEnd!==q.answerPageStart?`${q.answerPageStart}–${q.answerPageEnd}`:`${q.answerPageStart}`):'not recorded';const el=document.createElement('div');el.id='primary-runtime-modal';el.className='runtime-modal';el.innerHTML=`<div class="runtime-modal-backdrop"></div><div class="runtime-modal-card source-reference-modal" role="dialog" aria-modal="true" aria-labelledby="source-modal-title"><button class="runtime-modal-close" aria-label="Close">×</button><p class="eyebrow">Original source reference</p><h2 id="source-modal-title">${esc(q.source)}</h2><dl><div><dt>Source file</dt><dd>${esc(q.sourceFile||'Source PDF')}</dd></div><div><dt>Source question</dt><dd>${esc(sourceQLabel(q))}</dd></div><div><dt>Question page</dt><dd>${esc(q.questionPage||'—')}</dd></div><div><dt>Answer page</dt><dd>${esc(answerRange)}</dd></div></dl><p class="source-reference-note">The full source book/PDF is not redistributed by this website. Use the filename and page number above in your own authorised copy to compare typography, figures or wording against the original page.</p></div>`;document.body.appendChild(el);el.querySelectorAll('.runtime-modal-backdrop,.runtime-modal-close').forEach(x=>x.addEventListener('click',closePrimaryModal));document.addEventListener('keydown',function once(e){if(e.key==='Escape'){closePrimaryModal();document.removeEventListener('keydown',once)}});el.querySelector('.runtime-modal-close')?.focus({preventScroll:true})}
function openFigureLightbox(src,alt='Source figure'){closePrimaryModal();const el=document.createElement('div');el.id='primary-runtime-modal';el.className='runtime-modal figure-modal';el.innerHTML=`<div class="runtime-modal-backdrop"></div><div class="figure-modal-card" role="dialog" aria-modal="true" aria-label="Expanded source figure"><div class="figure-modal-toolbar"><span>Pinch or use + / − to zoom</span><button data-zoom="out" aria-label="Zoom out">−</button><button data-zoom="reset" aria-label="Reset zoom">100%</button><button data-zoom="in" aria-label="Zoom in">+</button><button class="runtime-modal-close" aria-label="Close">×</button></div><div class="figure-viewport"><img src="${esc(src)}" alt="${esc(alt)}"></div></div>`;document.body.appendChild(el);let scale=1;const img=el.querySelector('img'),reset=()=>{scale=1;img.style.transform='scale(1)';el.querySelector('[data-zoom="reset"]').textContent='100%'};const set=d=>{scale=Math.max(.5,Math.min(4,scale+d));img.style.transform=`scale(${scale})`;el.querySelector('[data-zoom="reset"]').textContent=`${Math.round(scale*100)}%`};el.querySelector('[data-zoom="in"]').addEventListener('click',()=>set(.25));el.querySelector('[data-zoom="out"]').addEventListener('click',()=>set(-.25));el.querySelector('[data-zoom="reset"]').addEventListener('click',reset);el.querySelectorAll('.runtime-modal-backdrop,.runtime-modal-close').forEach(x=>x.addEventListener('click',closePrimaryModal));document.addEventListener('keydown',function once(e){if(e.key==='Escape'){closePrimaryModal();document.removeEventListener('keydown',once)}});el.querySelector('.runtime-modal-close')?.focus({preventScroll:true})}
function handleAction(e){const a=e.currentTarget.dataset.action;if(a==='resume-autosave'){resumeDraft(readAutosave())}else if(a==='discard-autosave'){clearAutosave();render()}else if(a==='resume-saved-study'){continueStudy(e.currentTarget.dataset.studyKey)}else if(a==='discard-saved-study'){if(confirm('Remove this saved Study session?')){deleteStudySnapshot(e.currentTarget.dataset.studyKey);render()}}else if(a==='start-set'){startFromSet(e.currentTarget.closest('[data-set-card]'))}else if(a==='continue-study'){continueStudy(e.currentTarget.closest('[data-set-card]').dataset.studyKey)}else if(a==='start-mock'){const count=Number(document.getElementById('mock-count').value),domains=[...document.querySelectorAll('[data-mock-domain]:checked')].map(x=>x.value),levels=[...document.querySelectorAll('[data-mock-level]:checked')].map(x=>x.value),shuffle=Boolean(document.getElementById('mock-shuffle')?.checked),useTimer=Boolean(document.getElementById('mock-use-timer')?.checked),mins=useTimer?Number(document.getElementById('mock-minutes').value):null;if(!domains.length){alert('Select at least one domain.');return}if(!levels.length){alert('Select at least one level.');return}let pool=QUESTIONS.filter(q=>domains.includes(q.domain)&&levels.includes(q.level));if(shuffle)pool=[...pool].sort(()=>Math.random()-.5);pool=pool.slice(0,Math.min(count,pool.length));const domainLabel=domains.length>1?'Mixed domains':domains[0],levelLabel=levels.length>1?'Mixed levels':levels[0];startSession({kind:'mock',mode:useTimer?'timed':'test',title:'Primary Mock Exam',subtitle:`${domainLabel} · ${levelLabel}${shuffle?' · Randomised':''}`,questionIds:pool.map(q=>q.id),durationMinutes:mins,meta:{domains,levels,shuffle}})}else if(a==='check-answer')checkAnswer(Number(e.currentTarget.dataset.qid));else if(a==='show-explanation'){activeSession.expandedIds.add(Number(e.currentTarget.dataset.qid));saveAutosave('explanation');renderSessionPreserveScroll(Number(e.currentTarget.dataset.qid))}else if(a==='hide-explanation'){activeSession.expandedIds.delete(Number(e.currentTarget.dataset.qid));saveAutosave('explanation');renderSessionPreserveScroll(Number(e.currentTarget.dataset.qid))}else if(a==='flag'){const id=Number(e.currentTarget.dataset.qid),p=getProgress();p.flags[id]=!p.flags[id];setProgress(p);saveAutosave('flag');renderSessionPreserveScroll(id)}else if(a==='prev-question')moveQuestion(-1);else if(a==='next-question')moveQuestion(1);else if(a==='submit-session')submitSession(false);else if(a==='toggle-nav'){const nav=document.getElementById('question-nav');nav?.classList.remove('nav-hidden');nav?.classList.toggle('is-open');const open=nav?.classList.contains('is-open');nav?.querySelectorAll('[data-action="toggle-nav"]').forEach(btn=>{btn.setAttribute('aria-expanded',String(open));if(btn.classList.contains('navigator-toggle'))btn.textContent=open?'Close ▾':'Open ▴';else btn.textContent=open?'⌄':'⌃'})}else if(a==='exit-session'){saveAutosave('exit');activeSession=null;navigate('home')}else if(a==='review-queue')reviewQueue();else if(a==='export-progress'){exportProgress()}else if(a==='import-progress'){document.getElementById('progress-import-file')?.click()}else if(a==='post-discussion'){const qid=Number(e.currentTarget.dataset.qid),panel=e.currentTarget.closest('.discussion-panel'),ta=panel?.querySelector('.discussion-compose>textarea'),text=ta?.value||'';runDiscussionAction(async()=>{await postDiscussionComment(qid,text);if(ta)ta.value=''},e.currentTarget)}else if(a==='reply-discussion'){discussionReplyTarget={qid:Number(e.currentTarget.dataset.qid),commentId:e.currentTarget.dataset.commentId};updateDiscussionPanelDOM(discussionReplyTarget.qid);requestAnimationFrame(()=>document.querySelector(`[data-reply-text="${CSS.escape(discussionReplyTarget.commentId)}"]`)?.focus())}else if(a==='cancel-reply-discussion'){const qid=Number(e.currentTarget.dataset.qid);discussionReplyTarget=null;updateDiscussionPanelDOM(qid)}else if(a==='send-reply-discussion'){const qid=Number(e.currentTarget.dataset.qid),cid=e.currentTarget.dataset.commentId,panel=e.currentTarget.closest('.discussion-panel'),ta=panel?.querySelector(`[data-reply-text="${CSS.escape(cid)}"]`),text=ta?.value||'';runDiscussionAction(()=>postDiscussionComment(qid,text,cid),e.currentTarget)}else if(a==='report-discussion'){const qid=Number(e.currentTarget.dataset.qid),cid=e.currentTarget.dataset.commentId;runDiscussionAction(()=>reportDiscussionComment(qid,cid),e.currentTarget)}else if(a==='delete-discussion'){const qid=Number(e.currentTarget.dataset.qid),cid=e.currentTarget.dataset.commentId;if(confirm('Delete your comment? Replies will remain visible.'))runDiscussionAction(()=>deleteDiscussionComment(qid,cid),e.currentTarget)}else if(a==='open-search-question'){const id=Number(e.currentTarget.dataset.qid);startSession({kind:'search',mode:'study',title:'Search result',subtitle:sourceLabel(metaQuestionById(id)||{}),questionIds:[id],studyKey:'',durationMinutes:null})}else if(a==='view-source'){openSourceModal(Number(e.currentTarget.dataset.qid))}else if(a==='reset-all'){if(confirm('Reset all Primary Revision progress, flags, autosaves and saved Study sessions?')){Object.values(KEYS).forEach(k=>localStorage.removeItem(k));activeSession=null;render()}}}
function syncMobileMenu(){const menu=document.querySelector('.mobile-bottom-menu');if(!menu)return;const show=window.matchMedia('(max-width:780px)').matches&&routeState.name!=='session';menu.hidden=!show;document.documentElement.classList.toggle('mobile-menu-visible',show)}
let navigatorLastScrollY=0,navigatorScrollTick=false;
function updateNavigatorAutoHide(){navigatorScrollTick=false;const nav=document.getElementById('question-nav');if(!nav||!window.matchMedia('(max-width:780px)').matches){navigatorLastScrollY=window.scrollY;return}if(nav.classList.contains('is-open')){nav.classList.remove('nav-hidden');navigatorLastScrollY=window.scrollY;return}const y=window.scrollY,delta=y-navigatorLastScrollY;if(y<80||delta<-8)nav.classList.remove('nav-hidden');else if(delta>10)nav.classList.add('nav-hidden');navigatorLastScrollY=y}
window.addEventListener('scroll',()=>{if(navigatorScrollTick)return;navigatorScrollTick=true;requestAnimationFrame(updateNavigatorAutoHide)},{passive:true});
window.addEventListener('resize',syncMobileMenu,{passive:true});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveAutosave('hidden')});window.addEventListener('pagehide',()=>saveAutosave('pagehide'));window.addEventListener('beforeunload',()=>saveAutosave('beforeunload'));autosaveTimer=setInterval(()=>{if(document.visibilityState==='visible')saveAutosave('periodic')},15000);
// Route bootstrap. A direct #/session refresh resumes the current autosave if possible.
function fromHash(){const h=location.hash.replace(/^#\/?/,'');if(!h)return{name:'home'};const [a,b]=h.split('/');if(a==='topics')return b?{name:'topic',params:{name:decodeURIComponent(b)}}:{name:'topics'};if(a==='sources')return b?{name:'source',params:{code:b}}:{name:'sources'};if(a==='mock')return{name:'mock'};if(a==='saved')return{name:'saved'};if(a==='discussions')return{name:'discussions'};if(a==='search')return{name:'search'};if(a==='discussion'&&b)return{name:'discussion',params:{id:Number(b)}};if(a==='session')return{name:'session'};return{name:'home'}}
window.addEventListener('hashchange',async()=>{const r=fromHash();routeState=r;verseIndex=(verseIndex+1)%VERSES.length;window.scrollTo({top:0,left:0,behavior:'auto'});try{if(r.name==='session'&&!activeSession)activeSession=draftToSession(readAutosave());if(r.name==='session'&&activeSession)await ensureQuestionDetails(activeSession.questionIds);if(r.name==='discussion'&&r.params?.id)await ensureQuestionDetails([r.params.id])}catch(err){alert(err?.message||err)}render();requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:'auto'}))});
// Make route buttons update the URL without relying on full reloads.
const oldNavigate=navigate;navigate=function(name,params={}){let hash='#/';if(name==='topics')hash='#/topics';else if(name==='topic')hash='#/topics/'+encodeURIComponent(params.name);else if(name==='sources')hash='#/sources';else if(name==='source')hash='#/sources/'+params.code;else if(name==='mock')hash='#/mock';else if(name==='saved')hash='#/saved';else if(name==='discussions')hash='#/discussions';else if(name==='search')hash='#/search';else if(name==='discussion')hash='#/discussion/'+Number(params.id);else if(name==='session')hash='#/session';else hash='#/';const same=location.hash===hash;if(!same){window.scrollTo({top:0,left:0,behavior:'auto'});location.hash=hash;return}oldNavigate(name,params);requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:'auto'}))};
const initial=fromHash();routeState=initial;async function bootPrimaryRevision(){app.innerHTML=appLoading('Loading question index…');try{await loadBankIndex();if(initial.name==='session'){activeSession=draftToSession(readAutosave());if(activeSession)await ensureQuestionDetails(activeSession.questionIds)}if(initial.name==='discussion'&&initial.params?.id)await ensureQuestionDetails([initial.params.id]);render()}catch(err){bankLoadError=err?.message||String(err);app.innerHTML=`<div class="app-loading error"><span class="app-loading-mark">PR</span><strong>Unable to load the question bank.</strong><small>${esc(bankLoadError)}</small><button class="primary-button" onclick="location.reload()">Retry</button></div>`}}if(window.__PRIMARY_GATE_UNLOCKED__)bootPrimaryRevision();else window.addEventListener('primary-gate-unlocked',bootPrimaryRevision,{once:true});
window.addEventListener('online',()=>{if(!window.__PRIMARY_GATE_UNLOCKED__)return;if(discussionFirebaseState!=='ready'){discussionInitPromise=null;initFirebaseDiscussions().catch(()=>{})}});window.addEventListener('offline',()=>{discussionFirebaseState='offline';discussionFirebaseError='Discussions require an internet connection.';document.querySelectorAll('.discussion-panel').forEach(p=>updateDiscussionPanelDOM(Number(p.dataset.discussionQid)));if(routeState.name==='discussions')render()});function startFirebaseAfterPrimaryGate(){if(!window.__PRIMARY_GATE_UNLOCKED__)return;setTimeout(()=>initFirebaseDiscussions().catch(()=>{}),0)}if(window.__PRIMARY_GATE_UNLOCKED__)startFirebaseAfterPrimaryGate();else window.addEventListener('primary-gate-unlocked',startFirebaseAfterPrimaryGate,{once:true});
